package com.trustvault.document;

import com.trustvault.audit.AuditService; import com.trustvault.common.CurrentUser; import com.trustvault.user.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.FileSystemResource; import org.springframework.core.io.Resource; import org.springframework.http.MediaType; import org.springframework.security.access.AccessDeniedException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.nio.file.*; import java.security.MessageDigest; import java.time.*; import java.util.*;

@Service
public class DocumentService {
 private static final Set<String> ALLOWED_EXT=Set.of("pdf","docx","xlsx","png","jpg","jpeg","txt"); private static final long MAX_SIZE=10L*1024*1024;
 private final VaultDocumentRepository documents; private final DocumentPermissionRepository permissions; private final AppUserRepository users; private final CurrentUser current; private final AuditService audit; private final Path storage;
 public DocumentService(VaultDocumentRepository documents,DocumentPermissionRepository permissions,AppUserRepository users,CurrentUser current,AuditService audit,@Value("${trustvault.storage-dir:./private-storage}") String storageDir){this.documents=documents;this.permissions=permissions;this.users=users;this.current=current;this.audit=audit;this.storage=Paths.get(storageDir).toAbsolutePath().normalize();try{Files.createDirectories(this.storage);}catch(IOException e){throw new IllegalStateException("Cannot initialize private document storage",e);}}
 @Transactional(readOnly=true) public List<VaultDocument> search(String q,String category,String owner,LocalDate from,LocalDate to){AppUser u=current.get();return documents.search(u.getId(),u.getRole()==Role.ADMIN,blankNull(q),blankNull(category),blankNull(owner),from==null?null:from.atStartOfDay(ZoneOffset.UTC).toInstant(),to==null?null:to.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant());}
 @Transactional public VaultDocument upload(MultipartFile file,String title,String description,String category){AppUser actor=current.get(); if(actor.getRole()==Role.VIEWER) throw new AccessDeniedException("Viewers cannot upload documents"); validate(file);String original=StringUtils.cleanPath(Objects.requireNonNullElse(file.getOriginalFilename(),"document"));String ext=extension(original);String key=UUID.randomUUID()+"."+ext;Path dest=resolve(key);try(InputStream in=file.getInputStream()){Files.copy(in,dest,StandardCopyOption.REPLACE_EXISTING);}catch(IOException e){throw new IllegalStateException("Unable to store document",e);}try{VaultDocument d=new VaultDocument(title.trim(),description,category.trim(),original,key,cleanContentType(file.getContentType()),file.getSize(),sha256(dest),actor);d=documents.save(d);audit.record(actor.getEmail(),"DOCUMENT_UPLOAD","SUCCESS",d.getId(),d.getTitle(),"Uploaded document");return d;}catch(Exception e){try{Files.deleteIfExists(dest);}catch(IOException ignored){}throw e;}}
 @Transactional(readOnly=true) public VaultDocument getReadable(UUID id){VaultDocument d=documents.findById(id).orElse(null);if(d==null){audit.record(current.get().getEmail(),"DOCUMENT_VIEW","DENIED",id,null,"Document not found or inaccessible");throw new NoSuchElementException("Document not found");}if(!canRead(d,current.get())){audit.record(current.get().getEmail(),"DOCUMENT_VIEW","DENIED",id,d.getTitle(),"Insufficient permission");throw new AccessDeniedException("You do not have access to this document");}audit.record(current.get().getEmail(),"DOCUMENT_VIEW","SUCCESS",id,d.getTitle(),"Document metadata viewed");return d;}
 @Transactional public DownloadedFile download(UUID id){VaultDocument d=documents.findById(id).orElse(null);if(d==null||!canRead(d,current.get())){audit.record(current.get().getEmail(),"DOCUMENT_DOWNLOAD","DENIED",id,d==null?null:d.getTitle(),"Download denied");throw new NoSuchElementException("Document not found or access denied");}Path p=resolve(d.getStorageKey());if(!Files.isRegularFile(p)){throw new IllegalStateException("Stored file is missing");}audit.record(current.get().getEmail(),"DOCUMENT_DOWNLOAD","SUCCESS",id,d.getTitle(),"SHA-256="+d.getSha256());return new DownloadedFile(new FileSystemResource(p),d.getOriginalFilename(),d.getContentType());}
 @Transactional public void update(UUID id,String title,String description,String category){VaultDocument d=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found"));AppUser actor=current.get();if(!canEdit(d,actor)){audit.record(actor.getEmail(),"DOCUMENT_EDIT","DENIED",id,d.getTitle(),"Edit denied");throw new AccessDeniedException("You cannot edit this document");}d.setTitle(title.trim());d.setDescription(description);d.setCategory(category.trim());audit.record(actor.getEmail(),"DOCUMENT_EDIT","SUCCESS",id,d.getTitle(),"Document metadata updated");}
 @Transactional public void delete(UUID id){VaultDocument d=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found"));AppUser actor=current.get();if(actor.getRole()!=Role.ADMIN&&!d.getOwner().getId().equals(actor.getId())){audit.record(actor.getEmail(),"DOCUMENT_DELETE","DENIED",id,d.getTitle(),"Delete denied");throw new AccessDeniedException("Only the owner or administrator can delete this document");}String key=d.getStorageKey(),title=d.getTitle();UUID did=d.getId();permissions.deleteAll(permissions.findByDocument_IdOrderByGrantedAtDesc(id));documents.delete(d);audit.record(actor.getEmail(),"DOCUMENT_DELETE","SUCCESS",did,title,"Document deleted");try{Files.deleteIfExists(resolve(key));}catch(IOException e){throw new IllegalStateException("Metadata deleted but file cleanup failed",e);}}
 @Transactional public void grant(UUID id,UUID userId,AccessLevel level){VaultDocument d=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found"));AppUser actor=current.get();requireOwnerOrAdmin(d,actor);AppUser target=users.findById(userId).orElseThrow(()->new NoSuchElementException("Employee not found"));if(target.getId().equals(d.getOwner().getId()))throw new IllegalArgumentException("Owner already has access");DocumentPermission p=permissions.findByDocument_IdAndUser_Id(id,userId).orElse(null);if(p==null)permissions.save(new DocumentPermission(d,target,level,actor));else p.setAccessLevel(level);audit.record(actor.getEmail(),"PERMISSION_GRANTED","SUCCESS",id,d.getTitle(),"Granted "+level+" to "+target.getEmail());}
 @Transactional public void revoke(UUID id,UUID userId){VaultDocument d=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found"));AppUser actor=current.get();requireOwnerOrAdmin(d,actor);AppUser target=users.findById(userId).orElseThrow(()->new NoSuchElementException("Employee not found"));permissions.deleteByDocument_IdAndUser_Id(id,userId);audit.record(actor.getEmail(),"PERMISSION_REVOKED","SUCCESS",id,d.getTitle(),"Revoked access for "+target.getEmail());}
 @Transactional(readOnly=true) public boolean sharesForCurrentUserCanEdit(UUID id){ VaultDocument d=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found")); AppUser u=current.get(); return canEdit(d,u); }
 @Transactional(readOnly=true) public List<DocumentPermission> shares(UUID id){VaultDocument d=documents.findById(id).orElseThrow(()->new NoSuchElementException("Document not found"));requireOwnerOrAdmin(d,current.get());return permissions.findByDocument_IdOrderByGrantedAtDesc(id);}
 private boolean canRead(VaultDocument d,AppUser u){if(u.getRole()==Role.ADMIN||d.getOwner().getId().equals(u.getId()))return true;return permissions.findByDocument_IdAndUser_Id(d.getId(),u.getId()).isPresent();}
 private boolean canEdit(VaultDocument d,AppUser u){if(u.getRole()==Role.ADMIN||d.getOwner().getId().equals(u.getId()))return true;return permissions.findByDocument_IdAndUser_Id(d.getId(),u.getId()).map(p->p.getAccessLevel()==AccessLevel.EDIT).orElse(false);}
 private void requireOwnerOrAdmin(VaultDocument d,AppUser u){if(u.getRole()!=Role.ADMIN&&!d.getOwner().getId().equals(u.getId()))throw new AccessDeniedException("Only the owner or administrator can manage sharing");}
 private void validate(MultipartFile f){if(f==null||f.isEmpty())throw new IllegalArgumentException("Choose a non-empty file");if(f.getSize()>MAX_SIZE)throw new IllegalArgumentException("Maximum file size is 10 MB");String name=StringUtils.cleanPath(Objects.requireNonNullElse(f.getOriginalFilename(),""));if(name.contains("..")||name.contains("/")||name.contains("\\"))throw new IllegalArgumentException("Invalid filename");String ext=extension(name);if(!ALLOWED_EXT.contains(ext))throw new IllegalArgumentException("File type not allowed. Accepted: PDF, DOCX, XLSX, PNG, JPG, TXT");}
 private String extension(String name){int i=name.lastIndexOf('.');if(i<1||i==name.length()-1)throw new IllegalArgumentException("File extension required");return name.substring(i+1).toLowerCase(Locale.ROOT);}
 private String cleanContentType(String ct){return ct==null||ct.isBlank()?MediaType.APPLICATION_OCTET_STREAM_VALUE:ct.substring(0,Math.min(100,ct.length()));}
 private Path resolve(String key){Path p=storage.resolve(key).normalize();if(!p.startsWith(storage))throw new IllegalArgumentException("Invalid storage key");return p;}
 private String sha256(Path p){try(InputStream in=Files.newInputStream(p)){MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[8192];int n;while((n=in.read(b))>0)md.update(b,0,n);return HexFormat.of().formatHex(md.digest());}catch(Exception e){throw new IllegalStateException("Could not calculate file checksum",e);}}
 private String blankNull(String s){return s==null||s.isBlank()?null:s.trim();}
 public record DownloadedFile(Resource resource,String filename,String contentType){}
}
